INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(649,0,0,'NO, NO, NO! Please!',12,0,100,0,0,0,''),
(653,0,0,'ANYWHERE BUT THE BRIDGE!',12,0,100,0,0,0,''),
(694,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Bloodscalp Axe Thrower'),
(697,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Bloodscalp Shaman'),
(701,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Bloodscalp Mystic'),
(951,0,0,'BY THE LIGHT BE RENEWED!',12,0,100,0,0,0,'Brother Paxton'),
(951,0,1,'AND I LAY MY HANDS UPON YOU!',12,0,100,0,0,0,'Brother Paxton'),
(951,0,2,'Let the Holy Light embrace you!',12,0,100,0,0,0,'Brother Paxton'),
(951,1,0,'Be healed, $gbrother:sister;!',12,0,100,0,0,0,'Brother Paxton'),
(951,1,1,'FIGHT ON, $GBROTHER:SISTER;!',12,0,100,0,0,0,'Brother Paxton'),
(1059,0,0,'Skullsplitter... is... forever... mon...',12,0,100,0,0,0,'Ana\'thek the Cruel'),
(1355,0,0,'By th\' Light, it worked! Grimnur\'s brilliant... oh, I hope all the pinchin\' didn\'t hurt ye too much... But when ye taste the meat, ye\'ll know it\'s worth it!',12,0,100,5,0,0,''),
(1379,0,0,'I\'m off. Stay safe - I\'ll be back as quickly as I\'m able.',12,7,100,0,0,0,'Miran'),
(1449,0,0,'Get ready everyone!  Here come de apes!',14,0,100,5,0,0,''),
(1477,0,0,'Remember when Danath gathered all the mercenaries of Stormwind together and we marched to fight at Nethergarde?',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,1,'I tell ye, I don\'t miss the Great War at all. I remember when we fought at Darrowmere. All night in the fog, lying in a muddy trench.',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,2,'I miss the dwarven ale we used to get at that inn in Lordaeron. Remember that fight we started there?',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,3,'Less than a hundred of us, and over a thousand orcs. Only a handful of us managed to walk away from that one.',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,4,'The best had to have been the look on Perenolde\'s face when our army comes marchin\' right up to his front door. What a battle!',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,5,'Battling that band of Twilight Hammer in the Morass, I could think of better places for a war.',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,6,'Ahh yes, now I remember, your wedding night wasn\'t it?',12,7,100,0,0,0,'Christoph Faral'),
(1477,0,7,'Ahh the Glustewelt twins!',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,0,'I still have the scars from that night.',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,1,'Broke both me legs that night. How could I forget?',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,2,'I woke up in a bed in Northshire three weeks later. Don\'t remember a damn thing.',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,3,'Wasn\'t that the night we had to pick up my thumb and carry it in your smoke pouch?',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,4,'I have a piece of iron in my back that will remind me of that night for the rest of my days.',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,5,'Course I remember that night. Two inches to the left and you\'d be drinking with that elf, Morris. That was my best shirt, too.',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,6,'Was that the third or fourth time you nearly got me gutted trying one of your crazy stunts?',12,7,100,0,0,0,'Christoph Faral'),
(1477,1,7,'Aye and thanks for letting me carry my own hand back to the priests that night.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,0,'Hehe, wimp.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,1,'You screamed like a little girl, funniest thing I ever saw.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,2,'It all worked out in the end.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,3,'Let\'s not even begin comparing battle scars, my friend.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,4,'Never seen anyone move so fast in my whole life.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,5,'You are constantly surprising me with what a person can live through.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,6,'Well, you\'re still here. I\'d say that is something worth drinking to.',12,7,100,0,0,0,'Christoph Faral'),
(1477,2,7,'You can thank me anytime for making your life more interesting.',12,7,100,0,0,0,'Christoph Faral'),
(1478,0,0,'Hey Reese, give me an\' Christoph another round.',12,7,100,0,0,0,'Aedis Brom'),
(1478,1,0,'A warm tavern and a cold ale. What more could we ask for?',12,7,100,0,0,0,'Aedis Brom'),
