(39097,1,0,'I, ah...',12,0,100,0,0,0,''),
(39097,2,0,'Lilian, I...',12,0,100,0,0,0,''),
(39117,0,0,'Very well.  Follow me.',12,0,100,0,0,0,''),
(39117,1,0,'Now it is time for us to begin.',12,0,100,0,0,0,''),
