(39117,4,0,'Resist the Lich King\'s will, Devlin!  Come to us!',14,0,100,22,0,0,''),
(40737,0,0,'There are too many! Shaman, do something!',14,0,100,396,0,0,''),
(40737,1,0,'Rest while you can, men. That wasn\'t the last of them....',14,0,100,396,0,0,''),
(40737,2,0,'Brace yourselves, men!',14,0,100,396,0,0,''),
(40737,3,0,'Make them pay!',14,0,100,396,0,0,''),
(40737,4,0,'Stay alert! Don\'t let them drag you away!',14,0,100,396,0,0,''),
(40737,5,0,'Don\'t give up! Fight! Fight for the Alliance!',14,0,100,396,0,0,''),
(40737,6,0,'Their numbers are... endless...',14,0,100,396,0,0,''),
(40737,7,0,'My men - they\'re all taken... Go! Save youselves!',14,0,100,396,0,0,''),
